import type { EntrySourceOptions } from "plumix";

import { SHARED_CACHE_ENTRYPOINT } from "./shared-cache.js";

/**
 * The module-worker entry: a gateway `export default { fetch, scheduled }` and
 * the named entrypoint Workers Caching sits in front of.
 */
export function generateEntry({ configModule }: EntrySourceOptions): string {
  const lines = [
    "// Generated by plumix — do not edit.",
    "// Regenerated from plumix.config.ts on each build.",
    "",
    'import { WorkerEntrypoint } from "cloudflare:workers";',
    'import { buildApp, createRuntimeHandler, renderDevBootErrorResponse } from "plumix/runtime";',
    // Imported rather than spelled out: string-literal code is unreachable to
    // the compiler, linter and tests.
    'import { serveThroughGateway, surfaceScheduledFailure } from "@plumix/runtime-cloudflare";',
    // `{}` in dev; in build, the client environment's parsed
    // `.vite/manifest.json`.
    'import assetManifest from "virtual:plumix/asset-manifest";',
    // Each plugin's compiled catalogs by locale, lazy-imported, so SSR block
    // renders resolve plugin strings for the request locale.
    'import pluginCatalogs from "virtual:plumix/plugin-catalogs";',
    'import catalogLocales from "virtual:plumix/catalog-locales";',
    `import config from ${JSON.stringify(configModule)};`,
    // It binds the shared entrypoint, so it must evaluate before the app
    // connects its slots.
    'import { sharedEntrypointCached } from "virtual:plumix-cloudflare/workers-caching";',
    "",
    // Empty when no config slot contributes a worker export, such as a Durable
    // Object class.
    'export * from "virtual:plumix/worker-exports";',
    "",
    // buildApp derives its dev object from `process.env.PLUMIX_DEV` (the
    // single dev signal the plumix Vite plugin statically replaces), so the
    // worker passes no dev flag.
    "const appPromise = buildApp(config, {",
    "  assetManifest,",
    "  pluginCatalogs,",
    "  catalogLocales,",
    "});",
    "let handler;",
    "",
    // The handler contract is runtime-neutral: a `Request` plus one invocation.
    // This is the only place that knows the Worker's positional `(env, ctx)`.
    "const invocation = (env, ctx) => ({ env, waitUntil: (promise) => ctx.waitUntil(promise) });",
    "",
    "function serve(app, request, env, ctx) {",
    "  handler ??= createRuntimeHandler(app);",
    "  return handler.fetch(request, invocation(env, ctx));",
    "}",
    "",
    // Workers Caching sits in front of this entrypoint alone (wrangler config
    // turns it off for the default export), so a hit never runs the app.
    `export class ${SHARED_CACHE_ENTRYPOINT} extends WorkerEntrypoint {`,
    "  async fetch(request) {",
    "    return serve(await appPromise, request, this.env, this.ctx);",
    "  }",
    // Reached over RPC, which Workers Caching never answers, because a purge
    // clears only what the calling entrypoint stored.
    "  purge(options) {",
    "    return this.ctx.cache.purge(options);",
    "  }",
    "}",
    "",
    "export default {",
    "  async fetch(request, env, ctx) {",
    "    let app;",
    "    try {",
    "      app = await appPromise;",
    "    } catch (bootError) {",
    // Statically false in production, so this collapses to `throw bootError;`
    // and the renderer tree-shakes out.
    "      if (process.env.PLUMIX_DEV) {",
    "        return renderDevBootErrorResponse(bootError);",
    "      }",
    "      throw bootError;",
    "    }",
    "    return serveThroughGateway(request, {",
    "      app,",
    `      sharedCache: sharedEntrypointCached ? (forwarded) => ctx.exports.${SHARED_CACHE_ENTRYPOINT}.fetch(forwarded) : null,`,
    "      serve: (visitor) => serve(app, visitor, env, ctx),",
    "    });",
    "  },",
    "  async scheduled(event, env, ctx) {",
    "    const app = await appPromise;",
    "    handler ??= createRuntimeHandler(app);",
    // `?.` rather than a guard: an adapter with no `scheduled` reports
    // nothing, and a report of nothing fails nothing (#2361).
    "    const report = await handler.scheduled?.(event, invocation(env, ctx));",
    "    surfaceScheduledFailure(report, event);",
    "  },",
    "};",
    "",
  ];
  return lines.join("\n");
}
